using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class FitGeneratedRiderGrips {
 static Transform Target(Transform root,string name,Vector3 p){var g=new GameObject(name);g.transform.SetParent(root,false);g.transform.localPosition=p;return g.transform;}
 public static object Main(){if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Edit required");EditorSceneManager.OpenScene("Assets/ShooterSurvival/Scenes/Tools/Jamsil.unity");var d=UnityEngine.Object.FindFirstObjectByType<Chapter45Director>();File.Copy(d.gameObject.scene.path,"outputs/chapter45-detailed-design-2026-10-03/scene-recovery/Jamsil-before-rider-contact-fit.unity",false);var rows=new List<object>();const string folder="Assets/ShooterSurvival/Models/Chapters/Chapters45/DetailedCharacters20261003/CH07/";foreach(var h in d.hazards.Where(h=>h.name.Contains("kickboard")||h.name.Contains("motorcycle"))){bool bike=h.name.Contains("motorcycle");var pose=h.body.GetComponentInChildren<Chapter45RiderPose>(true);var a=pose.animator;var root=pose.transform;AssetDatabase.LoadAssetAtPath<AnimationClip>(folder+"idle.anim").SampleAnimation(a.gameObject,0);var leftFoot=pose.leftFoot.rotation;var rightFoot=pose.rightFoot.rotation;AssetDatabase.LoadAssetAtPath<AnimationClip>(folder+(bike?"bikeride":"kickride")+".anim").SampleAnimation(a.gameObject,0);var leftHand=pose.leftHand.rotation;var rightHand=pose.rightHand.rotation;Vector3 leftPalm=(pose.leftHand.position-pose.leftForearm.position).normalized*.055f,rightPalm=(pose.rightHand.position-pose.rightForearm.position).normalized*.055f;pose.leftGrip.localPosition=new Vector3(-.22f,bike?.94f:1.105f,bike?.44f:.265f);pose.rightGrip.localPosition=new Vector3(.22f,bike?.94f:1.105f,bike?.44f:.265f);pose.leftGrip.position-=leftPalm;pose.rightGrip.position-=rightPalm;pose.leftGrip.rotation=leftHand;pose.rightGrip.rotation=rightHand;if(!bike){pose.leftFootTarget=Target(root,"Left deck foot anchor",new Vector3(.015f,.245f,-.20f));pose.rightFootTarget=Target(root,"Right deck foot anchor",new Vector3(-.015f,.245f,.03f));}else{pose.leftFootTarget.localPosition=new Vector3(-.19f,.38f,.05f);pose.rightFootTarget.localPosition=new Vector3(.19f,.38f,.05f);}pose.leftFootTarget.rotation=leftFoot;pose.rightFootTarget.rotation=rightFoot;pose.ApplyPose();EditorUtility.SetDirty(pose);rows.Add(new{h.name,ownHandAxesPreserved=true,feetFixedToDeckOrFootrests=true,collidersUnchanged=true});}EditorSceneManager.MarkSceneDirty(d.gameObject.scene);EditorSceneManager.SaveScene(d.gameObject.scene);return new{items=rows};}
}
